import uuid
from datetime import datetime
from typing import Optional

from sqlalchemy import DateTime, ForeignKey, Index, String, Text, text
from sqlalchemy.dialects.postgresql import JSONB, UUID
from sqlalchemy.orm import Mapped, mapped_column

from app.models.base import Base, TimestampMixin

REPORT_TYPES = ("voting", "financial", "attendance")
REPORT_FORMATS = ("csv", "xlsx", "pdf")
REPORT_JOB_STATUSES = ("pending", "processing", "completed", "failed")


class ReportExportJob(TimestampMixin, Base):
    """One requested CSV/Excel/PDF report export, generated by a background
    Celery task rather than in the request — reports assemble non-trivial
    data (financial breakdowns, full attendee lists) and render a file,
    which doesn't belong on the request/response cycle.

    idempotency_key + the unique index below are what "prevent double
    clicks" actually means here: a retried/duplicated request with the same
    key returns the existing job instead of enqueueing a second render.
    The index is partial (excludes 'failed') so a failed job never blocks a
    later retry with the same params — matching
    ReportExportJobRepository.get_reusable, which already only reuses
    pending/processing/completed jobs."""

    __tablename__ = "report_export_jobs"
    __table_args__ = (
        Index(
            "uq_report_export_idempotency",
            "requested_by", "idempotency_key",
            unique=True,
            postgresql_where=text("status != 'failed'"),
        ),
    )

    job_id: Mapped[uuid.UUID] = mapped_column(
        UUID(as_uuid=True), primary_key=True, default=uuid.uuid4
    )
    requested_by: Mapped[uuid.UUID] = mapped_column(
        UUID(as_uuid=True), ForeignKey("users.user_id"), nullable=False
    )
    report_type: Mapped[str] = mapped_column(String(20), nullable=False)
    format: Mapped[str] = mapped_column(String(10), nullable=False)
    # {source_id, source_kind, range, ...} — shape depends on report_type,
    # see ReportExportService for what each one reads.
    params: Mapped[dict] = mapped_column(JSONB, nullable=False, default=dict)
    # Explicit if the client sends one (e.g. a UI-generated key per submit),
    # else a deterministic hash of (report_type, format, params) so an
    # accidental duplicate submit collapses to the same job even without
    # client cooperation — see ReportExportService._derive_idempotency_key.
    idempotency_key: Mapped[str] = mapped_column(String(64), nullable=False)
    status: Mapped[str] = mapped_column(String(20), default="pending", nullable=False)
    download_url: Mapped[Optional[str]] = mapped_column(Text, nullable=True)
    error: Mapped[Optional[str]] = mapped_column(Text, nullable=True)
    completed_at: Mapped[Optional[datetime]] = mapped_column(
        DateTime(timezone=True), nullable=True
    )
